class Solution:

	def matchPairs(self, nuts, bolts, n):
		ord = ['!', '#', '$', '%', '&', '*', '@', '^', '~']
		matcher = dict()
		for i in nuts:
			matcher[i] = 1
		for j in bolts:
			matcher[j] += 1
		res = []
		for o in ord:
			if matcher.get(o) == 2:
				res.append(o)
		nuts.clear()
		nuts.extend(res)
		bolts.clear()
		bolts.extend(res)
